def load_firebase_credential():
    service_account_json = os.environ.get("FIREBASE_SERVICE_ACCOUNT_JSON")

    if service_account_json:
        try:
            service_account_info = json.loads(service_account_json)
        except json.JSONDecodeError as exc:
            raise RuntimeError("FIREBASE_SERVICE_ACCOUNT_JSON geçerli bir JSON değil.") from exc

        if "private_key" in service_account_info:
            service_account_info["private_key"] = service_account_info["private_key"].replace("\\n", "\n")

        return credentials.Certificate(service_account_info)

    try:
        firebase_secret = st.secrets.get("firebase_service_account")
    except Exception:
        firebase_secret = None

    if firebase_secret:
        service_account_info = dict(firebase_secret)

        if "private_key" in service_account_info:
            service_account_info["private_key"] = service_account_info["private_key"].replace("\\n", "\n")

        return credentials.Certificate(service_account_info)

    service_account_path = os.environ.get("FIREBASE_SERVICE_ACCOUNT_PATH")

    if not service_account_path:
        raise RuntimeError("Firebase service account bilgisi bulunamadı.")

    if not os.path.exists(service_account_path):
        raise RuntimeError(f"Firebase service account dosyası bulunamadı: {service_account_path}")

    return credentials.Certificate(service_account_path)


@st.cache_resource(show_spinner=False)
def get_firestore_client():
    if not firebase_admin._apps:
        cred = load_firebase_credential()
        firebase_admin.initialize_app(cred)
    return firestore.client()


def now_local():
    """Tanımlı saat dilimindeki güncel zamanı döndürür."""
    return datetime.now(ZoneInfo(TIMEZONE_NAME))


def now_iso():
    """Güncel zamanı sıralanabilir ISO metni olarak döndürür."""
    return now_local().isoformat(timespec="microseconds")


def today_key():
    """Günlük kullanım kayıtları için yerel tarih anahtarını döndürür."""
    return now_local().date().isoformat()


def to_local_datetime(value):
    """Firestore/ISO tarih değerini İstanbul saatine çevirir."""
    if not value:
        return None

    try:
        if isinstance(value, datetime):
            dt = value
        else:
            text = str(value).strip()
            if not text:
                return None
            text = text.replace("Z", "+00:00")
            try:
                dt = datetime.fromisoformat(text)
            except ValueError:
                # Çok eski/farklı kayıtlar için toleranslı yedek formatlar.
                for fmt in ["%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%d/%m/%Y %H:%M:%S"]:
                    try:
                        dt = datetime.strptime(text[:19], fmt)
                        break
                    except ValueError:
                        dt = None
                if dt is None:
                    return None

        local_tz = ZoneInfo(TIMEZONE_NAME)
        if dt.tzinfo is None:
            # Firebase/Cloud tarafında naive gelen kayıtları UTC kabul edip İstanbul'a çeviriyoruz.
            # Bu, panelde görülen 3 saat eksik görünme problemini düzeltir.
            dt = dt.replace(tzinfo=ZoneInfo("UTC"))

        return dt.astimezone(local_tz)
    except Exception:
        return None


def format_display_datetime(value):
    """Panel tarihlerini '12.49 12/06/2026' biçiminde gösterir."""
    dt = to_local_datetime(value)
    if not dt:
        return ""
    return dt.strftime("%H.%M %d/%m/%Y")


def datetime_sort_value(value):
    """Tablolarda tarih sıralaması için güvenli datetime döndürür."""
    dt = to_local_datetime(value)
    if dt:
        return dt
    return datetime.min.replace(tzinfo=ZoneInfo(TIMEZONE_NAME))


def is_allowed_email(email):
    email = email.strip().lower()
    if "@" not in email:
        return False
    domain = email.split("@", 1)[1]
    allowed = ALLOWED_EMAIL_DOMAIN.lstrip("@")
    return domain == allowed or domain.endswith("." + allowed)


def role_for_email(email):
    return "admin" if email.strip().lower() in ADMIN_EMAILS else "user"


# =========================================================
# FIREBASE AUTH REST HELPERS
# =========================================================

def firebase_post(endpoint, payload):
    if not FIREBASE_API_KEY:
        raise RuntimeError("FIREBASE_API_KEY .env içinde tanımlı değil.")
    url = f"https://identitytoolkit.googleapis.com/v1/{endpoint}?key={FIREBASE_API_KEY}"
    response = requests.post(url, json=payload, timeout=30)
    try:
        data = response.json()
    except Exception:
        data = {}
    if response.status_code >= 400:
        message = data.get("error", {}).get("message", "Firebase hatası")
        raise RuntimeError(message)
    return data


def firebase_refresh_id_token(refresh_token):
    """Refresh token ile yeni Firebase ID token üretir."""
    if not FIREBASE_API_KEY:
        raise RuntimeError("FIREBASE_API_KEY .env içinde tanımlı değil.")

    url = f"https://securetoken.googleapis.com/v1/token?key={FIREBASE_API_KEY}"
    response = requests.post(
        url,
        data={"grant_type": "refresh_token", "refresh_token": refresh_token},
        timeout=30,
    )

    try:
        data = response.json()
    except Exception:
        data = {}

    if response.status_code >= 400:
        message = data.get("error", {}).get("message", "Firebase token yenileme hatası")
        raise RuntimeError(message)

    return data


def store_firebase_session_tokens(auth_data):
    """Firebase oturum tokenlarını session state içinde saklar."""
    id_token = auth_data.get("idToken") or auth_data.get("id_token")
    refresh_token = auth_data.get("refreshToken") or auth_data.get("refresh_token")

    if id_token:
        st.session_state.firebase_id_token = id_token
    if refresh_token:
        st.session_state.firebase_refresh_token = refresh_token


def ensure_valid_firebase_session(expected_uid=None):
    """ID tokenı doğrular, gerekirse refresh token ile yeniler."""
    id_token = st.session_state.get("firebase_id_token")
    refresh_token = st.session_state.get("firebase_refresh_token")

    if not id_token:
        return False

    try:
        decoded = fb_auth.verify_id_token(id_token, check_revoked=True)
    except Exception:
        if not refresh_token:
            return False
        try:
            refreshed = firebase_refresh_id_token(refresh_token)
            store_firebase_session_tokens(refreshed)
            decoded = fb_auth.verify_id_token(
                st.session_state.get("firebase_id_token"),
                check_revoked=True,
            )
        except Exception:
            return False

    if expected_uid and decoded.get("uid") != expected_uid:
        return False

    return True


def firebase_sign_up(email, password):
    return firebase_post("accounts:signUp", {"email": email, "password": password, "returnSecureToken": True})


def firebase_sign_in(email, password):
    return firebase_post("accounts:signInWithPassword", {"email": email, "password": password, "returnSecureToken": True})


def firebase_update_display_name(id_token, username):
    return firebase_post("accounts:update", {"idToken": id_token, "displayName": username, "returnSecureToken": True})


def firebase_update_password(id_token, new_password):
    return firebase_post("accounts:update", {"idToken": id_token, "password": new_password, "returnSecureToken": True})


def firebase_send_email_verification(id_token):
    return firebase_post("accounts:sendOobCode", {"requestType": "VERIFY_EMAIL", "idToken": id_token})


def firebase_send_password_reset(email):
    return firebase_post("accounts:sendOobCode", {"requestType": "PASSWORD_RESET", "email": email})


def firebase_get_account_info(id_token):
    data = firebase_post("accounts:lookup", {"idToken": id_token})
    users = data.get("users", [])
    if not users:
        raise RuntimeError("Firebase kullanıcı bilgisi bulunamadı.")
    return users[0]


