def user_doc_ref(firebase_uid):
    db = get_firestore_client()
    return db.collection("users").document(firebase_uid)


def username_is_taken(username, except_uid=None):
    db = get_firestore_client()
    username_clean = username.strip().lower()
    docs = db.collection("users").where("username_lower", "==", username_clean).limit(5).stream()
    for doc in docs:
        if except_uid is None or doc.id != except_uid:
            return True
    return False


def get_user_by_uid(firebase_uid):
    doc = user_doc_ref(firebase_uid).get()
    if not doc.exists:
        return None
    data = doc.to_dict()
    data["firebase_uid"] = firebase_uid
    data["id"] = firebase_uid
    return data


def get_user_by_username_local(username):
    db = get_firestore_client()
    docs = db.collection("users").where("username_lower", "==", username.strip().lower()).limit(1).stream()
    for doc in docs:
        data = doc.to_dict()
        data["firebase_uid"] = doc.id
        data["id"] = doc.id
        return data
    return None


def get_or_create_firestore_user(firebase_uid, username, email, email_verified):
    email_clean = email.strip().lower()
    username_clean = username.strip() if username and username.strip() else email_clean.split("@")[0]
    username_lower = username_clean.lower()
    existing = get_user_by_uid(firebase_uid)
    if existing:
        payload = {
            "username": existing.get("username", username_clean),
            "username_lower": existing.get("username_lower", username_lower),
            "email": email_clean,
            "role": role_for_email(email_clean),
            "email_verified": bool(email_verified),
            "updated_at": now_iso(),
        }
        user_doc_ref(firebase_uid).set(payload, merge=True)
        return get_user_by_uid(firebase_uid)
    if username_is_taken(username_clean):
        username_clean = f"{email_clean.split('@')[0]}_{firebase_uid[:5]}"
        username_lower = username_clean.lower()
    payload = {
        "firebase_uid": firebase_uid,
        "username": username_clean,
        "username_lower": username_lower,
        "email": email_clean,
        "role": role_for_email(email_clean),
        "email_verified": bool(email_verified),
        "created_at": now_iso(),
        "updated_at": now_iso(),
    }
    user_doc_ref(firebase_uid).set(payload)
    return get_user_by_uid(firebase_uid)


def delete_query_results(query, batch_size=100):
    db = get_firestore_client()
    while True:
        docs = list(query.limit(batch_size).stream())
        if not docs:
            break
        batch = db.batch()
        for doc in docs:
            batch.delete(doc.reference)
        batch.commit()
        if len(docs) < batch_size:
            break


def delete_user_everywhere(user):
    firebase_uid = user["firebase_uid"]
    db = get_firestore_client()
    delete_query_results(db.collection("chat_logs").where("user_uid", "==", firebase_uid))
    delete_query_results(db.collection("chat_messages").where("user_uid", "==", firebase_uid))
    user_doc_ref(firebase_uid).delete()
    try:
        fb_auth.delete_user(firebase_uid)
    except Exception as e:
        raise RuntimeError(f"Firebase Auth kullanıcısı silinemedi: {e}")


def resolve_identifier_to_email(identifier):
    identifier_clean = identifier.strip().lower()
    if not identifier_clean:
        return None, "E-posta veya kullanıcı adı girmelisin."
    if "@" in identifier_clean:
        if not is_allowed_email(identifier_clean):
            return None, f"Sadece {ALLOWED_EMAIL_DOMAIN} uzantılı YTÜ e-posta adresleriyle giriş yapılabilir."
        try:
            fb_auth.get_user_by_email(identifier_clean)
        except fb_auth.UserNotFoundError:
            return None, "Sistemde bu e-posta adresiyle kayıt bulunamadı."
        return identifier_clean, None
    user = get_user_by_username_local(identifier_clean)
    if not user:
        return None, "Sistemde bu kullanıcı adıyla kayıt bulunamadı."
    return user["email"], None


def authenticate_user(identifier, password):
    """Kullanıcı adı veya e-posta ile Firebase oturumu açar."""
    email, resolve_error = resolve_identifier_to_email(identifier)
    if resolve_error:
        return None, resolve_error

    try:
        sign_in_data = firebase_sign_in(email, password)
        id_token = sign_in_data["idToken"]
        account = firebase_get_account_info(id_token)
        firebase_uid = account["localId"]
        email_verified = bool(account.get("emailVerified", False))

        if not email_verified:
            return None, "E-posta adresin doğrulanmamış. Lütfen Firebase doğrulama mailindeki bağlantıya tıkla."

        user = get_or_create_firestore_user(
            firebase_uid=firebase_uid,
            username=account.get("displayName") or email.split("@")[0],
            email=email,
            email_verified=email_verified,
        )
        store_firebase_session_tokens(sign_in_data)
        st.session_state.user = user
        return user, None
    except Exception as error:
        error_text = str(error)
        if any(key in error_text for key in ["INVALID_LOGIN_CREDENTIALS", "INVALID_PASSWORD"]):
            return None, "Şifre hatalı."
        if "USER_DISABLED" in error_text:
            return None, "Bu kullanıcı hesabı devre dışı bırakılmış."
        print(f"[AUTH] Giriş hatası: {error_text}")
        return None, "Giriş sırasında bir hata oluştu. Lütfen tekrar deneyin."


def register_user(username, email, password):
    email_clean = email.strip().lower()
    username_clean = username.strip()
    if not is_allowed_email(email_clean):
        return False, f"Sadece {ALLOWED_EMAIL_DOMAIN} uzantılı YTÜ e-posta adresleriyle kayıt olunabilir."
    if username_is_taken(username_clean):
        return False, "Bu kullanıcı adı zaten alınmış."
    try:
        fb_auth.get_user_by_email(email_clean)
        return False, "Bu e-posta adresiyle kayıtlı bir hesap var."
    except fb_auth.UserNotFoundError:
        pass
    try:
        sign_up_data = firebase_sign_up(email_clean, password)
        id_token = sign_up_data["idToken"]
        firebase_update_display_name(id_token, username_clean)
        firebase_send_email_verification(id_token)
        return True, "Kayıt oluşturuldu. E-postana gelen doğrulama bağlantısına tıkladıktan sonra giriş yapabilirsin."
    except Exception as e:
        error_text = str(e)
        if "EMAIL_EXISTS" in error_text:
            return False, "Bu e-posta adresiyle kayıtlı bir hesap var."
        if "WEAK_PASSWORD" in error_text:
            return False, "Şifre zayıf. En az 6 karakter kullanmalısın."
        return False, f"Kayıt sırasında hata oluştu: {error_text}"


def send_password_reset_after_check(username, email):
    email_clean = email.strip().lower()
    username_clean = username.strip()
    if not is_allowed_email(email_clean):
        return False, f"Sadece {ALLOWED_EMAIL_DOMAIN} uzantılı YTÜ e-posta adresleri kullanılabilir."
    try:
        auth_user = fb_auth.get_user_by_email(email_clean)
    except fb_auth.UserNotFoundError:
        return False, "Bu e-posta adresiyle kayıtlı bir hesap bulunamadı."
    local_user = get_user_by_uid(auth_user.uid)
    username_ok = False
    if local_user and local_user.get("username_lower") == username_clean.lower():
        username_ok = True
    if auth_user.display_name and auth_user.display_name.strip().lower() == username_clean.lower():
        username_ok = True
    if not username_ok:
        return False, "Girilen kullanıcı adı ve e-posta bilgileri eşleşmiyor."
    try:
        firebase_send_password_reset(email_clean)
        return True, "Şifre sıfırlama bağlantısı e-posta adresine gönderildi."
    except Exception as e:
        return False, f"Şifre sıfırlama bağlantısı gönderilemedi: {e}"


def count_query_documents(query):
    """Firestore sorgusundaki belge sayısını aggregation ile döndürür."""
    try:
        result = query.count().get()
        for row in result:
            for item in row:
                value = getattr(item, "value", None)
                if value is not None:
                    return int(value)
    except Exception:
        pass

    return sum(1 for _ in query.stream())


def count_today_questions(user):
    """Kullanıcının bugün başarıyla tamamlanan soru sayısını döndürür."""
    if not user:
        return 0

    query = get_firestore_client().collection("chat_logs") \
        .where("user_uid", "==", user["firebase_uid"]) \
        .where("date_key", "==", today_key())
    return count_query_documents(query)


def user_daily_usage_ref(user, date_value=None):
    """Kullanıcının günlük kota belgesini döndürür."""
    date_value = date_value or today_key()
    safe_uid = re.sub(r"[^a-zA-Z0-9_-]+", "_", user["firebase_uid"])
    return get_firestore_client().collection("user_daily_usage").document(f"{date_value}_{safe_uid}")


def get_user_question_count(user):
    """Kullanıcının günlük kota sayacını döndürür."""
    if not user or user.get("role") == "admin":
        return 0

    doc = user_daily_usage_ref(user).get()
    if doc.exists:
        return int((doc.to_dict() or {}).get("count", 0) or 0)

    return count_today_questions(user)


def reserve_user_question(user, question=None):
    """Kullanıcı için bir soru hakkını atomik olarak rezerve eder."""
    if user.get("role") == "admin":
        return True, None

    db = get_firestore_client()
    ref = user_daily_usage_ref(user)
    baseline = count_today_questions(user)
    date_value = today_key()

    @google_firestore.transactional
    def reserve(transaction):
        snapshot = ref.get(transaction=transaction)
        data = snapshot.to_dict() or {}
        used = int(data.get("count", baseline) or 0) if snapshot.exists else baseline

        if used >= DAILY_USER_LIMIT:
            return False, used

        transaction.set(ref, {
            "user_uid": user["firebase_uid"],
            "date_key": date_value,
            "count": used + 1,
            "last_question": question or "",
            "updated_at": now_iso(),
            "updated_at_server": google_firestore.SERVER_TIMESTAMP,
        }, merge=True)
        return True, used + 1

    allowed, _ = reserve(db.transaction())
    if not allowed:
        return False, f"Bugünkü {DAILY_USER_LIMIT} soru hakkını doldurdun. Yarın tekrar deneyebilirsin."

    return True, None


def release_user_question_reservation(user):
    """Başarısız işlemde rezerve edilen kullanıcı hakkını geri verir."""
    if not user or user.get("role") == "admin":
        return

    db = get_firestore_client()
    ref = user_daily_usage_ref(user)

    @google_firestore.transactional
    def release(transaction):
        snapshot = ref.get(transaction=transaction)
        if not snapshot.exists:
            return
        data = snapshot.to_dict() or {}
        count = max(0, int(data.get("count", 0) or 0) - 1)
        transaction.set(ref, {
            "count": count,
            "updated_at": now_iso(),
            "updated_at_server": google_firestore.SERVER_TIMESTAMP,
        }, merge=True)

    release(db.transaction())


def can_ask_question(user):
    """Kullanıcının günlük soru hakkı olup olmadığını kontrol eder."""
    if user["role"] == "admin":
        return True, None

    used = get_user_question_count(user)
    if used >= DAILY_USER_LIMIT:
        return False, f"Bugünkü {DAILY_USER_LIMIT} soru hakkını doldurdun. Yarın tekrar deneyebilirsin."

    return True, None


def get_or_create_guest_id():
    """Misafir oturumu için güvenli bir kimlik üretir veya mevcut kimliği döndürür."""
    guest_id = None

    try:
        value = st.query_params.get("guest_id")
        guest_id = value[0] if isinstance(value, list) and value else value
    except Exception:
        guest_id = None

    if not guest_id:
        guest_id = st.session_state.get("guest_id")

    if not isinstance(guest_id, str) or not re.fullmatch(r"[A-Za-z0-9_-]{8,128}", guest_id):
        guest_id = secrets.token_urlsafe(16)

    st.session_state.guest_id = guest_id
    st.session_state.guest_session_id = guest_id

    try:
        if st.query_params.get("guest_id") != guest_id:
            st.query_params["guest_id"] = guest_id
    except Exception:
        pass

    return guest_id


def get_client_ip():
    """Streamlit oturum headerlarından doğrulanabilir istemci IP adresini döndürür."""
    try:
        headers = {str(key).lower(): str(value) for key, value in st.context.headers.items()}
    except Exception:
        return None

    for header_name in ["x-forwarded-for", "x-real-ip", "cf-connecting-ip"]:
        raw_value = headers.get(header_name, "")
        if not raw_value:
            continue
        candidate = raw_value.split(",", 1)[0].strip()
        try:
            return str(ipaddress.ip_address(candidate))
        except ValueError:
            continue

    return None


def hash_client_ip(ip_address):
    """IP adresini ham değer saklamadan günlük limit anahtarına dönüştürür."""
    if not ip_address:
        return None

    salt = GUEST_IP_HASH_SALT or FIREBASE_API_KEY or "ytu-rag-guest-limit"
    return hashlib.sha256(f"{salt}:{ip_address}".encode("utf-8")).hexdigest()


def get_guest_usage_identity(guest_id=None):
    """Misafir kota kaydı için guest ID ve IP hash bilgisini üretir."""
    guest_id = guest_id or get_or_create_guest_id()
    ip_hash = hash_client_ip(get_client_ip())
    safe_guest_id = re.sub(r"[^a-zA-Z0-9_-]+", "_", guest_id)
    usage_key = f"ip_{ip_hash}" if ip_hash else f"guest_{safe_guest_id}"

    return {
        "guest_id": guest_id,
        "ip_hash": ip_hash,
        "usage_key": usage_key,
    }


def guest_usage_ref(guest_id=None, date_value=None):
    """Misafirin günlük kota belgesini döndürür."""
    identity = get_guest_usage_identity(guest_id)
    date_value = date_value or today_key()
    doc_id = f"{date_value}_{identity['usage_key']}"
    return get_firestore_client().collection("guest_usage").document(doc_id)


def get_guest_question_count():
    """Misafirin günlük kota sayacını döndürür."""
    date_value = today_key()
    doc = guest_usage_ref(date_value=date_value).get()

    if not doc.exists:
        st.session_state.guest_question_count = 0
        st.session_state.guest_date_key = date_value
        return 0

    count = int((doc.to_dict() or {}).get("count", 0) or 0)
    st.session_state.guest_question_count = count
    st.session_state.guest_date_key = date_value
    return count


def reserve_guest_question(question=None):
    """Misafir için bir soru hakkını atomik olarak rezerve eder."""
    init_guest_state()
    db = get_firestore_client()
    identity = get_guest_usage_identity()
    date_value = today_key()
    ref = guest_usage_ref(identity["guest_id"], date_value)

    @google_firestore.transactional
    def reserve(transaction):
        snapshot = ref.get(transaction=transaction)
        data = snapshot.to_dict() or {}
        used = int(data.get("count", 0) or 0)

        if used >= DAILY_GUEST_LIMIT:
            return False, used

        transaction.set(ref, {
            "guest_id": identity["guest_id"],
            "ip_hash": identity["ip_hash"],
            "date_key": date_value,
            "count": used + 1,
            "last_question": question or "",
            "updated_at": now_iso(),
            "updated_at_server": google_firestore.SERVER_TIMESTAMP,
        }, merge=True)
        return True, used + 1

    allowed, new_count = reserve(db.transaction())
    st.session_state.guest_question_count = new_count
    st.session_state.guest_date_key = date_value

    if not allowed:
        return False, "Misafir soru hakkın doldu. Devam etmek için giriş yapabilir veya kayıt olabilirsin."

    return True, None


def release_guest_question_reservation():
    """Başarısız işlemde rezerve edilen misafir hakkını geri verir."""
    db = get_firestore_client()
    ref = guest_usage_ref()

    @google_firestore.transactional
    def release(transaction):
        snapshot = ref.get(transaction=transaction)
        if not snapshot.exists:
            return 0
        data = snapshot.to_dict() or {}
        count = max(0, int(data.get("count", 0) or 0) - 1)
        transaction.set(ref, {
            "count": count,
            "updated_at": now_iso(),
            "updated_at_server": google_firestore.SERVER_TIMESTAMP,
        }, merge=True)
        return count

    st.session_state.guest_question_count = release(db.transaction())


def can_guest_ask_question():
    """Misafirin günlük soru hakkı olup olmadığını kontrol eder."""
    init_guest_state()
    used = get_guest_question_count()
    if used >= DAILY_GUEST_LIMIT:
        return False, "Misafir soru hakkın doldu. Devam etmek için giriş yapabilir veya kayıt olabilirsin."
    return True, None


def log_chat(
    user,
    session_id,
    question,
    answer,
    model_name,
    categories,
    sources,
    doc_count,
    direct_lookup=False,
    expanded_query=None,
    retrieval_debug=None,
    guest=False,
):
    """Başarıyla tamamlanan soru-cevap işlemini Firestore'a kaydeder ve log ID döndürür."""
    user = user or {}

    if guest:
        guest_id = get_or_create_guest_id()
        user_uid = f"guest_{guest_id}"
        username = "Misafir"
        email = ""
    else:
        user_uid = user.get("firebase_uid", "")
        username = user.get("username", "")
        email = user.get("email", "")

    payload = {
        "user_uid": user_uid,
        "username": username,
        "email": email,
        "guest": bool(guest),
        "session_id": session_id,
        "question": question,
        "answer": answer,
        "model_name": model_name,
        "detected_categories": categories or [],
        "retrieved_sources": sources or [],
        "retrieved_doc_count": int(doc_count or 0),
        "direct_lookup": bool(direct_lookup),
        "expanded_query": expanded_query or "",
        "retrieval_debug": retrieval_debug or {},
        "feedback_value": 0,
        "feedback_label": "",
        "feedback_icon": "",
        "feedback_comment": "",
        "date_key": today_key(),
        "created_at": now_iso(),
        "created_at_server": google_firestore.SERVER_TIMESTAMP,
    }

    doc_ref = get_firestore_client().collection("chat_logs").document()
    doc_ref.set(payload)
    return doc_ref.id


def save_message(user, session_id, role, content, log_id=None, sources=None):
    """Kayıtlı kullanıcının tek sohbet mesajını Firestore'a kaydeder."""
    payload = {
        "user_uid": user["firebase_uid"],
        "session_id": session_id,
        "role": role,
        "content": content,
        "created_at": now_iso(),
        "created_at_server": google_firestore.SERVER_TIMESTAMP,
    }

    if log_id:
        payload["log_id"] = log_id
    if sources:
        payload["sources"] = sources

    get_firestore_client().collection("chat_messages").add(payload)


def remove_latest_current_question(messages, current_question=None):
    """Geçmiş listesinden güncel kullanıcı sorusunun son kopyasını çıkarır."""
    rows = list(messages)
    if not current_question:
        return rows

    target = str(current_question).strip()
    for index in range(len(rows) - 1, -1, -1):
        row = rows[index]
        if row.get("role") == "user" and str(row.get("content", "")).strip() == target:
            del rows[index]
            break

    return rows


def get_recent_conversation_context(
    session_id,
    user=None,
    guest=False,
    max_messages=CONVERSATION_CONTEXT_MAX_MESSAGES,
    current_question=None,
):
    """LLM için son sohbet mesajlarını metin bağlamına dönüştürür."""
    if guest:
        rows = st.session_state.get("guest_messages", [])
    else:
        docs = get_firestore_client().collection("chat_messages") \
            .where("user_uid", "==", user["firebase_uid"]) \
            .where("session_id", "==", session_id) \
            .stream()
        rows = []
        for doc in docs:
            data = doc.to_dict() or {}
            data["_document_id"] = doc.id
            rows.append(data)
        rows.sort(key=lambda item: (item.get("created_at", ""), item.get("_document_id", "")))

    rows = remove_latest_current_question(rows, current_question)[-max_messages:]
    if not rows:
        return "Önceki konuşma yok."

    parts = []
    for row in rows:
        role_label = "Kullanıcı" if row.get("role") == "user" else "Asistan"
        content = str(row.get("content", ""))[:CONVERSATION_MESSAGE_CHAR_LIMIT]
        parts.append(f"{role_label}: {content}")

    return "\n".join(parts)


def get_admin_users_df():
    db = get_firestore_client()
    docs = db.collection("users").stream()
    rows = []
    for doc in docs:
        data = doc.to_dict() or {}
        created_at = data.get("created_at")
