def render_login_register_guest():
    init_guest_state()

    hdr_col, spacer, theme_col = st.columns([1.55, 0.35, 0.75], gap="medium")
    with hdr_col:
        render_header(single_line=True)
    with theme_col:
        render_theme_selector("login")

    if st.session_state.show_guest_chat:
        _, center, _ = st.columns([1, 6, 1])
        with center:
            if st.button("⬅️ Giriş Ekranına Dön"):
                st.session_state.show_guest_chat = False
                st.rerun()
            st.markdown("<h4 style='text-align:center;font-weight:950;'>🚶‍♂️ Misafir Sohbeti</h4>", unsafe_allow_html=True)
            chat_container = st.container(height=280)
            with chat_container:
                for msg in st.session_state.guest_messages:
                    render_chat_message(msg)

            if st.session_state.get("guest_pending_question"):
                pending_question = st.session_state.guest_pending_question
                with st.spinner("Mevzuat taranıyor..."):
                    final_cevap, retrieval_debug, sources, _, arama_sorusu = answer_question(pending_question, user=None, guest=True)

                log_id = None
                if retrieval_debug.get("error"):
                    release_guest_question_reservation()
                else:
                    log_id = log_chat(
                        user=None,
                        session_id=st.session_state.guest_session_id,
                        question=pending_question,
                        answer=final_cevap,
                        model_name=retrieval_debug.get("model_used", ACTIVE_MODEL),
                        categories=retrieval_debug.get("categories", []),
                        sources=sources,
                        doc_count=retrieval_debug.get("doc_count", 0),
                        direct_lookup=retrieval_debug.get("direct_lookup", False),
                        expanded_query=arama_sorusu,
                        retrieval_debug=retrieval_debug,
                        guest=True,
                    )

                st.session_state.guest_messages.append({
                    "role": "assistant",
                    "content": final_cevap,
                    "sources": sources,
                    "log_id": log_id,
                    "question": pending_question,
                    "model_name": retrieval_debug.get("model_used", ACTIVE_MODEL),
                    "categories": retrieval_debug.get("categories", []),
                    "guest": True,
                })
                st.session_state.guest_pending_question = None
                st.rerun()

            with st.container(key="guest_input_area"):
                with st.form("guest_form", clear_on_submit=True):
                    ic, sc = st.columns([0.95, 0.05], gap="small")
                    with ic:
                        user_prompt = st.text_input("", placeholder="Misafir olarak soru sorun...", label_visibility="collapsed")
                    with sc:
                        sub = st.form_submit_button("↑", use_container_width=True)
            if sub and user_prompt.strip():
                cleaned_prompt = user_prompt.strip()
                allowed, msg = reserve_guest_question(cleaned_prompt)
                if not allowed:
                    st.warning(msg)
                else:
                    st.session_state.guest_messages.append({"role": "user", "content": cleaned_prompt})
                    st.session_state.guest_pending_question = cleaned_prompt
                    st.rerun()
        return

    col_auth, col_guest = st.columns([1, 1], gap="large")
    with col_auth:
        st.markdown('<div class="auth-section-title">Kayıtlı Kullanıcı Girişi</div>', unsafe_allow_html=True)
        tab_login, tab_register, tab_forgot = st.tabs(["Giriş Yap", "Kaydol", "Şifremi Unuttum"])
        with tab_login:
            with st.form("login_form"):
                identifier = st.text_input("E-posta veya kullanıcı adı")
                password = st.text_input("Şifre", type="password")
                submitted = st.form_submit_button("Giriş Yap", use_container_width=True)
            if submitted:
                user, error = authenticate_user(identifier, password)
                if error:
                    st.error(error)
                else:
                    st.session_state.user = user
                    st.session_state.messages = []
                    st.session_state.session_id = secrets.token_urlsafe(16)
                    st.success("Giriş başarılı.")
                    st.rerun()
        with tab_register:
            st.caption(f"Yalnızca {ALLOWED_EMAIL_DOMAIN} e-posta adresleri kabul edilir.")
            with st.form("register_form"):
                username = st.text_input("Kullanıcı adı")
                email = st.text_input("E-posta", key="reg_email")
                password = st.text_input("Şifre", type="password", key="reg_pass")
                password2 = st.text_input("Şifre tekrar", type="password")
                submitted = st.form_submit_button("Kaydol", use_container_width=True)
            if submitted:
                email_clean = email.strip().lower()
                if not username.strip() or not email_clean or not password:
                    st.error("Kullanıcı adı, e-posta ve şifre zorunludur.")
                elif not is_allowed_email(email_clean):
                    st.error(f"Sadece {ALLOWED_EMAIL_DOMAIN} uzantılı e-posta adresleri kullanılabilir.")
                elif password != password2:
                    st.error("Şifreler eşleşmiyor.")
                elif len(password) < 6:
                    st.error("Şifre en az 6 karakter olmalı.")
                else:
                    ok, message = register_user(username, email_clean, password)
                    st.success(message) if ok else st.error(message)
        with tab_forgot:
            st.caption("Şifre sıfırlama için kullanıcı adı ve e-posta girmeniz gerekir.")
            with st.form("forgot_form"):
                username = st.text_input("Kullanıcı adı", key="forgot_user")
                email = st.text_input("E-posta", key="forgot_email")
                submitted = st.form_submit_button("Şifre Sıfırlama Linki Gönder", use_container_width=True)
            if submitted:
                if not username.strip() or not email.strip():
                    st.error("Kullanıcı adı ve e-posta birlikte girilmelidir.")
                else:
                    ok, message = send_password_reset_after_check(username, email)
                    st.success(message) if ok else st.error(message)
    with col_guest:
        st.markdown('<div class="auth-section-title">Hızlı Deneyim</div>', unsafe_allow_html=True)
        st.caption("Kayıt olmadan mevzuat asistanını test edin.")
        if st.button("Misafir Olarak Soru Sor", use_container_width=True, type="primary"):
            st.session_state.show_guest_chat = True
            st.rerun()



def render_modern_table(df, empty_text="Gösterilecek kayıt bulunamadı.", extra_class=""):
    if df is None or df.empty:
        st.markdown(f'<div class="modern-table-empty">{empty_text}</div>', unsafe_allow_html=True)
        return

    table_df = df.copy().fillna("")
    hidden_columns = [col for col in table_df.columns if str(col) == "id" or str(col).startswith("_")]
    if hidden_columns:
        table_df = table_df.drop(columns=hidden_columns)

    def safe_class(col):
        return "col-" + re.sub(r"[^a-zA-Z0-9_-]+", "_", str(col)).strip("_").lower()

    headers = "".join(
        f'<th class="{safe_class(col)}">{html.escape(str(col))}</th>'
        for col in table_df.columns
    )

    def cell_html(col, value):
        col_name = str(col)
        if col_name in ["Değerlendirme", "feedback"]:
            return feedback_icon_html(value)
        return html.escape(str(value))

    rows = []
    for _, row in table_df.iterrows():
        cells = "".join(
            f'<td class="{safe_class(col)}">{cell_html(col, row[col])}</td>'
            for col in table_df.columns
        )
        rows.append(f"<tr>{cells}</tr>")

    table_html = f'<table class="modern-table"><thead><tr>{headers}</tr></thead><tbody>{"".join(rows)}</tbody></table>'
    extra_class = str(extra_class or "").strip()
    wrap_class = "modern-table-wrap" + (f" {extra_class}" if extra_class else "")
    st.markdown(f'<div class="{wrap_class}">{table_html}</div>', unsafe_allow_html=True)

def render_admin_document_management():
    st.markdown("### Dosya / Kategori Yönetimi")

    st.info(
        "Bu ekranda .docx formatında yönerge veya yönetmelik yüklenebilir. "
        "Yüklenen dosya seçilen veya yeni oluşturulan kategori metadata'sı ile ChromaDB'ye eklenir. "
        "Yükleme sonrasında vektör veritabanı otomatik olarak yeniden oluşturulur."
    )

    st.markdown("#### Mevcut Dokümanlar")
    docs_df = get_documents_table_for_admin()

    if docs_df.empty:
        st.warning("data klasöründe listelenecek doküman bulunamadı.")
    else:
        display_cols = [
            col for col in [
                "file_name",
                "category_key",
                "admin_uploaded",
                "chunk_size",
                "chunk_overlap",
                "relative_path",
            ]
            if col in docs_df.columns
        ]
        docs_display = docs_df[display_cols].copy()
        if "admin_uploaded" in docs_display.columns:
            docs_display["admin_uploaded"] = docs_display["admin_uploaded"].apply(lambda value: "Evet" if bool(value) else "Hayır")
        docs_display = docs_display.rename(columns={
            "file_name": "Dosya Adı",
            "category_key": "Kategori Anahtarı",
            "admin_uploaded": "Admin Yüklemesi",
            "chunk_size": "Chunk Size",
            "chunk_overlap": "Chunk Overlap",
            "relative_path": "Dosya Yolu",
        })
        render_modern_table(docs_display, "Doküman kaydı bulunamadı.")

    st.markdown("---")
    st.markdown("#### Yeni Word Dokümanı Yükle")

    active_rules = get_active_category_rules()
    existing_categories = sorted(active_rules.keys())

    category_mode = st.radio(
        "Kategori işlemi",
        ["Mevcut kategoriye ekle", "Yeni kategori oluştur"],
        horizontal=True,
        key="admin_category_mode_selector",
    )

    with st.form("admin_upload_docx_form"):
        uploaded_file = st.file_uploader(
            "Word dokümanı seç (.docx)",
            type=["docx"],
            accept_multiple_files=False,
        )

        col_a, col_b = st.columns([1, 1])

        with col_a:
            st.caption(f"Seçili işlem: {category_mode}")

        with col_b:
            document_type = st.selectbox(
                "Doküman türü",
                ["Yönerge", "Yönetmelik", "Esas", "Kurul Kararı", "Diğer"],
            )

        if category_mode == "Mevcut kategoriye ekle":
            selected_category = st.selectbox(
                "Mevcut kategori",
                existing_categories,
                index=0 if existing_categories else None,
            )
            new_category_key = selected_category
            display_name = st.text_input(
                "Görünen kategori adı",
                value=active_rules.get(selected_category, {}).get("display_name", selected_category) if selected_category else "",
            )
        else:
            display_name = st.text_input(
                "Yeni kategori görünen adı",
                placeholder="Örn: Burs Yönergesi",
            )
            suggested_key = slugify_category_key(display_name) if display_name else ""
            new_category_key = st.text_input(
                "Yeni kategori anahtarı",
                value=suggested_key,
                placeholder="Örn: burs_yonergesi",
            )

        source_code = st.text_input(
            "Kaynak kodu / dosya kodu",
            placeholder="Örn: YÖ-150, DD-200",
        )

        normal_keywords_text = st.text_area(
            "Normal keywordler",
            placeholder="Her satıra bir keyword yazabilirsin. Örn:\nburs\nbaşarı bursu\nöğrenim desteği",
            height=110,
        )

        st.markdown("##### Güçlü keywordler")
        st.caption("Her güçlü keyword için ağırlığı ayrı ayrı seçebilirsin. Orta: +6, Güçlü: +10, Çok güçlü: +14")

        weighted_keywords_editor = []
        for index in range(1, 9):
            kw_col, weight_col = st.columns([3, 1])
            with kw_col:
                keyword_value = st.text_input(
                    f"Güçlü keyword {index}",
                    key=f"admin_weighted_keyword_{index}",
                    placeholder="Örn: burs başvuru şartları" if index == 1 else "",
                    label_visibility="collapsed",
                )
            with weight_col:
                weight_value = st.selectbox(
                    f"Ağırlık {index}",
                    ["Orta", "Güçlü", "Çok güçlü"],
                    index=1,
                    key=f"admin_weighted_keyword_weight_{index}",
                    label_visibility="collapsed",
                )
            weighted_keywords_editor.append({"Keyword": keyword_value, "Ağırlık": weight_value})

        st.caption(
            "Chunk önerisi: Uzun ve karmaşık maddelere sahip dokümanlarda daha yüksek chunk size; "
            "kısa ve net hükümler içeren dokümanlarda daha küçük chunk size tercih edilebilir. "
            "Overlap bağlam kopmasını azaltır ancak çok yüksek tutulursa tekrar ve veritabanı boyutu artar."
        )

        col_chunk_1, col_chunk_2 = st.columns([1, 1])

        with col_chunk_1:
            chunk_size = st.number_input(
                "Chunk size",
                min_value=MIN_CHUNK_SIZE,
                max_value=MAX_CHUNK_SIZE,
                value=800,
                step=50,
            )

        with col_chunk_2:
            chunk_overlap = st.number_input(
                "Chunk overlap",
                min_value=MIN_CHUNK_OVERLAP,
                max_value=MAX_CHUNK_OVERLAP,
                value=150,
                step=25,
            )

        st.caption("Dosya yüklendikten sonra vektör veritabanı otomatik olarak yeniden oluşturulur.")
        submitted = st.form_submit_button("Dosyayı Yükle ve Veritabanını Güncelle")

    if submitted:
        if uploaded_file is None:
            st.error("Lütfen .docx formatında bir dosya seç.")
            return

        if not uploaded_file.name.lower().endswith(".docx"):
            st.error("Sadece .docx formatı destekleniyor.")
            return

        category_key = slugify_category_key(new_category_key or display_name)

        if not category_key:
            st.error("Kategori anahtarı boş olamaz.")
            return

        if not display_name:
            display_name = category_key

        chunk_size_value, chunk_overlap_value, chunk_error = validate_admin_chunk_values(
            chunk_size,
            chunk_overlap,
        )

        if chunk_error:
            st.error(chunk_error)
            return

        normal_keywords = parse_keyword_text(normal_keywords_text)
        weighted_keywords = parse_weighted_keyword_rows(weighted_keywords_editor)

        try:
            ensure_dir(ADMIN_UPLOAD_DIR)

            saved_filename = safe_upload_filename(uploaded_file.name)
            saved_path = os.path.join(ADMIN_UPLOAD_DIR, saved_filename)

            with open(saved_path, "wb") as f:
                f.write(uploaded_file.getbuffer())

            file_key = os.path.splitext(saved_filename)[0]

            category_key = upsert_dynamic_category_rule(
                category_key=category_key,
                display_name=display_name,
                source_code=source_code,
                file_key=file_key,
                normal_keywords=normal_keywords,
                weighted_keywords=weighted_keywords,
                weight_level=None,
                chunk_size=chunk_size_value,
                chunk_overlap=chunk_overlap_value,
            )

            registry_entry = {
                "file_name": saved_filename,
                "relative_path": saved_path.replace("\\", "/"),
                "category_key": category_key,
                "display_name": display_name,
                "source_code": source_code.strip(),
                "document_type": document_type,
                "chunk_size": int(chunk_size_value),
                "chunk_overlap": int(chunk_overlap_value),
                "uploaded_at": now_iso(),
                "uploaded_by": st.session_state.get("user", {}).get("email", ""),
                "is_system_file": False,
                "admin_uploaded": True,
            }

            upsert_document_registry_entry(registry_entry)

            st.success(f"Dosya kaydedildi: {saved_filename}")
            st.info(f"Kategori: {category_key}")

            # Windows/local ortamda Chroma dosyalarının kilitli kalma riskini azaltmak için
            # ingest başlamadan önce cache ve vectorstore bağlantısı temizlenir.
            try:
                get_vector_db.clear()
            except Exception:
                pass

            try:
                st.cache_resource.clear()
            except Exception:
                pass

            try:
                st.cache_data.clear()
            except Exception:
                pass

            with st.spinner("Vektör veritabanı yeniden oluşturuluyor. Bu işlem biraz sürebilir..."):
                try:
                    from ingest import run_ingest
                except Exception as import_error:
                    raise RuntimeError(
                        "ingest.py içinden run_ingest fonksiyonu import edilemedi. "
                        "Önce güncel ingest.py dosyasını projeye eklemelisin."
                    ) from import_error

                result = run_ingest(
                    data_dir="data",
                    persist_dir=CHROMA_PATH,
                    temp_persist_dir="chroma_db_new",
                    dynamic_rules_path=DYNAMIC_RULES_PATH,
                    document_registry_path=DOCUMENT_REGISTRY_PATH,
                    safe_swap=True,
                )

            try:
                get_vector_db.clear()
            except Exception:
                pass

            try:
                st.cache_resource.clear()
            except Exception:
                pass

            try:
                st.cache_data.clear()
            except Exception:
                pass

            st.success(
                f"Vektör veritabanı güncellendi. "
                f"Toplam chunk: {result.get('chunk_count')}, "
                f"Chroma kayıt: {result.get('chroma_record_count')}"
            )

            if result.get("backup_dir"):
                st.caption(f"Eski veritabanı yedeği: {result.get('backup_dir')}")

            st.rerun()

        except Exception as e:
            st.error(f"Dosya yükleme / ingest işlemi başarısız oldu: {e}")

    st.markdown("---")
    st.markdown("#### Dinamik Kategori Kuralları")

    dynamic_rules = load_dynamic_rules()
    dynamic_categories = dynamic_rules.get("categories", {})

    if not dynamic_categories:
        st.info("Henüz admin panelinden eklenmiş dinamik kategori yok.")
    else:
        rows = []
        for key, rule in dynamic_categories.items():
            rows.append({
                "Kategori Anahtarı": key,
                "Görünen Ad": rule.get("display_name", ""),
                "Dosya Anahtarları": ", ".join(rule.get("files", [])),
                "Normal Keyword Sayısı": len(rule.get("keywords", [])),
                "Güçlü Keyword Sayısı": len(rule.get("weighted_keywords", [])),
                "Chunk Size": rule.get("chunk_size", ""),
                "Chunk Overlap": rule.get("chunk_overlap", ""),
            })

        render_modern_table(pd.DataFrame(rows), "Dinamik kategori kaydı bulunamadı.")

        with st.expander("dynamic_category_rules.json içeriğini göster", expanded=False):
            st.code(json.dumps(dynamic_rules, ensure_ascii=False, indent=2), language="json")


def feedback_icon_html(value):
    """Feedback ikonunu tablo/metriklerde renkli görsel olarak döndürür."""
    value = str(value or "").strip()
    if value == "👍":
        return f'<img class="feedback-icon-mini" src="{FEEDBACK_THUMB_UP_DATA_URI}" alt="Olumlu">'
    if value == "👎":
        return f'<img class="feedback-icon-mini" src="{FEEDBACK_THUMB_DOWN_DATA_URI}" alt="Olumsuz">'
    return "-"


