def prepare_feedback_display_df(df):
    """Feedback tablosunu admin paneli için Türkçe başlıklı hale getirir."""
    if df is None or df.empty:
        return pd.DataFrame()

    display_cols = [
        col for col in [
            "feedback",
            "question_category",
            "comment",
            "username",
            "email",
            "guest",
            "question",
            "answer_preview",
            "model_name",
            "detected_categories",
            "updated_at",
        ]
        if col in df.columns
    ]

    out = df[display_cols].copy()
    if "updated_at" in out.columns:
        out["updated_at"] = out["updated_at"].apply(format_display_datetime)
    if "guest" in out.columns:
        out["guest"] = out["guest"].apply(lambda value: "Evet" if bool(value) else "Hayır")
    if "question_category" in out.columns:
        out["question_category"] = out["question_category"].astype(str).replace("", "Kategori Yok")

    return out.rename(columns={
        "feedback": "Değerlendirme",
        "question_category": "Soru Kategorisi",
        "comment": "Yorum",
        "username": "Kullanıcı Adı",
        "email": "E-posta",
        "guest": "Misafir",
        "question": "Soru",
        "answer_preview": "Cevap Önizlemesi",
        "model_name": "Model",
        "detected_categories": "Tespit Edilen Kategoriler",
        "updated_at": "Güncellenme Tarihi",
    })

