def filter_question_history_df(df, search_text):
    """Sorularım/Sohbetlerim aramasını Ctrl+F mantığıyla tablo üzerinde uygular."""
    if df is None or df.empty:
        return df

    query = normalize_text(search_text or "").strip()
    if not query:
        return df

    searchable_columns = [
        col for col in [
            "Soru",
            "Cevap",
            "Model",
            "Tespit Edilen Kategoriler",
            "Getirilen Kaynaklar",
            "Kullanıcı Yorumu",
        ]
        if col in df.columns
    ]

    if not searchable_columns:
        return df

    mask = df[searchable_columns].astype(str).apply(
        lambda row: any(query in normalize_text(value) for value in row),
        axis=1,
    )
    return df[mask]


def render_selected_question_detail(df):
    """Arama sonucundan seçilen soru-cevap kaydını okunabilir biçimde gösterir."""
    if df is None or df.empty or "Soru" not in df.columns:
        return

    options = list(df.index)

    def option_label(index):
        row = df.loc[index]
        date_text = str(row.get("Tarih", "")).strip()
        question_text = truncate_text(row.get("Soru", ""), 90)
        return f"{date_text} — {question_text}" if date_text else question_text

    selected_index = st.selectbox(
        "Görüntülenecek soru",
        options,
        format_func=option_label,
        key="question_history_selected_item",
    )

    row = df.loc[selected_index]
    with st.expander("Seçilen soru ve cevabı görüntüle", expanded=True):
        st.markdown("**Soru**")
        st.write(row.get("Soru", ""))
        st.markdown("**Cevap**")
        st.write(row.get("Cevap", ""))

        meta_parts = []
        if str(row.get("Tarih", "")).strip():
            meta_parts.append(f"Tarih: {row.get('Tarih')}")
        if str(row.get("Model", "")).strip():
            meta_parts.append(f"Model: {row.get('Model')}")
        if str(row.get("Getirilen Chunk Sayısı", "")).strip():
            meta_parts.append(f"Getirilen Chunk Sayısı: {row.get('Getirilen Chunk Sayısı')}")
        if meta_parts:
            st.caption(" | ".join(meta_parts))

        if str(row.get("Tespit Edilen Kategoriler", "")).strip():
            st.markdown("**Tespit Edilen Kategoriler**")
            st.write(row.get("Tespit Edilen Kategoriler", ""))

        if str(row.get("Getirilen Kaynaklar", "")).strip():
            st.markdown("**Getirilen Kaynaklar**")
            st.write(row.get("Getirilen Kaynaklar", ""))


def render_my_questions(user):
    st.markdown("## Sorularım")
    st.caption("Son 100 soru, en yeniden en eskiye doğru listelenir. Arama kutusu soru, cevap, kategori ve kaynaklar içinde arama yapar.")

    df = get_logs_df(limit=100, user=user)
    if df.empty:
        st.info("Henüz soru kaydın yok.")
        return

    search_text = st.text_input(
        "Sohbetlerde ara",
        placeholder="Örn: staj, ÇAP, AGNO, yaz okulu, özel öğrenci...",
        key="question_history_search",
    )

    filtered_df = filter_question_history_df(df, search_text)

    if search_text.strip():
        st.caption(f"{len(filtered_df)} / {len(df)} kayıt eşleşti.")

    if filtered_df.empty:
        st.warning("Aramanla eşleşen soru bulunamadı.")
        return

    render_selected_question_detail(filtered_df)
    render_modern_table(filtered_df, "Henüz soru kaydın yok.", extra_class="question-history-table")


def render_account_settings(user):
    st.markdown("## Hesap Ayarları")
    st.text_input("Kullanıcı adı", value=user.get("username", ""), disabled=True)
    st.text_input("E-posta", value=user.get("email", ""), disabled=True)
    st.markdown("### Şifre Değiştir")
    with st.form("change_pass_form"):
        new_password = st.text_input("Yeni şifre", type="password")
        new_password2 = st.text_input("Yeni şifre tekrar", type="password")
        submitted = st.form_submit_button("Şifreyi Değiştir")
    if submitted:
        if not new_password or not new_password2:
            st.error("Yeni şifre alanları boş olamaz.")
        elif new_password != new_password2:
            st.error("Şifreler eşleşmiyor.")
        elif len(new_password) < 6:
            st.error("Şifre en az 6 karakter olmalı.")
        else:
            try:
                id_token = st.session_state.get("firebase_id_token")
                if not id_token:
                    raise RuntimeError("Oturum tokenı bulunamadı.")
                firebase_update_password(id_token, new_password)
                st.success("Şifren güncellendi.")
            except Exception as e:
                st.error(f"Şifre değiştirilemedi: {e}")
    with st.expander("Hesabı Sil", expanded=False):
        st.warning("Bu işlem hesabını ve soru geçmişini siler. Geri alınamaz.")
        confirm = st.text_input("Silmek için HESABIMI SIL yaz", key="delete_confirm")
        if st.button("Hesabımı Kalıcı Olarak Sil"):
            if confirm.strip() != "HESABIMI SIL":
                st.error("Onay metni doğru değil.")
            else:
                try:
                    delete_user_everywhere(user)
                    st.session_state.clear()
                    st.success("Hesabın silindi.")
                    st.rerun()
                except Exception as e:
                    st.error(f"Hesap silinemedi: {e}")


def render_chat(user):
    if "messages" not in st.session_state:
        st.session_state.messages = []
    if "session_id" not in st.session_state:
        st.session_state.session_id = secrets.token_urlsafe(16)

    # Sol: quota+logout  |  Orta: sohbet  |  Sağ: boş
    left_col, chat_col, right_col = st.columns([0.14, 0.72, 0.14], gap="medium")

    with left_col:
        # Quota ve çıkış alanı CSS ile sol alt tarafa yaklaştırılıyor.
        st.markdown('<div class="quota-col">', unsafe_allow_html=True)

        if user["role"] != "admin":
            used = get_user_question_count(user)
            kalan = max(0, DAILY_USER_LIMIT - used)
            quota_val = str(kalan)
        else:
            quota_val = "Sınırsız"

        st.markdown(f"""
        <div class="quota-block">
            <div>Günlük</div>
            <div>kalan</div>
            <div>soru</div>
            <div>hakkı: {quota_val}</div>
        </div>
        """, unsafe_allow_html=True)

        st.markdown('<div class="logout-wrap">', unsafe_allow_html=True)
        if st.button("Çıkış Yap", key="logout_btn", use_container_width=True):
            st.session_state.clear()
            st.rerun()
        st.markdown('</div>', unsafe_allow_html=True)
        st.markdown('</div>', unsafe_allow_html=True)

    with chat_col:
        st.markdown('<div class="chat-wrap">', unsafe_allow_html=True)
        chat_container = st.container(height=430)
        with chat_container:
            for message in st.session_state.messages:
                render_chat_message(message)

        if st.session_state.get("pending_question"):
            pending_question = st.session_state.pending_question
            with st.spinner("Mevzuat taranıyor, lütfen bekleyin..."):
                final_cevap, retrieval_debug, sources, context_docs, arama_sorusu = answer_question(
                    pending_question, user=user, guest=False)

            log_id = None
            if retrieval_debug.get("error"):
                release_user_question_reservation(user)
            else:
                log_id = log_chat(
                    user=user, session_id=st.session_state.session_id,
                    question=pending_question, answer=final_cevap, model_name=retrieval_debug.get("model_used", ACTIVE_MODEL),
                    categories=retrieval_debug.get("categories", []),
                    sources=sources, doc_count=retrieval_debug.get("doc_count", 0),
                    direct_lookup=retrieval_debug.get("direct_lookup", False),
                    expanded_query=arama_sorusu, retrieval_debug=retrieval_debug,
                )

            st.session_state.messages.append({
                "role": "assistant",
                "content": final_cevap,
                "sources": sources,
                "log_id": log_id,
                "question": pending_question,
                "model_name": retrieval_debug.get("model_used", ACTIVE_MODEL),
                "categories": retrieval_debug.get("categories", []),
                "guest": False,
            })
            save_message(user, st.session_state.session_id, "assistant", final_cevap, log_id=log_id, sources=sources)
            st.session_state.pending_question = None
            st.rerun()

        st.markdown('</div>', unsafe_allow_html=True)

        with st.container(key="chat_input_area"):
            with st.form("chat_form", clear_on_submit=True):
                ic, sc = st.columns([0.95, 0.05], gap="small")
                with ic:
                    user_prompt = st.text_input(
                        "Soru", placeholder="Örn: ÇAP yapmak için AGNO en az kaç olmalı?",
                        label_visibility="collapsed"
                    )
                with sc:
                    submitted = st.form_submit_button("↑", use_container_width=True)

    if submitted and user_prompt.strip():
        user_prompt = user_prompt.strip()
        allowed, limit_message = reserve_user_question(user, user_prompt)
        if not allowed:
            st.warning(limit_message)
            return
        st.session_state.messages.append({"role": "user", "content": user_prompt})
        save_message(user, st.session_state.session_id, "user", user_prompt)
        st.session_state.pending_question = user_prompt
        st.rerun()


